package com.iotfirmware.core

import scala.collection.mutable
import java.time.Instant
import java.security.MessageDigest

// Lightweight template engine for IoT device status pages
object TemplateEngine {
  private val templateCache = mutable.Map[String, CompiledTemplate]()
  private val safeBuiltins = Set("deviceId", "timestamp", "firmwareVersion", "uptime")

  sealed trait TemplateNode
  case class LiteralNode(text: String) extends TemplateNode
  case class VariableNode(name: String) extends TemplateNode
  case class ExpressionNode(expr: String) extends TemplateNode

  case class CompiledTemplate(nodes: List[TemplateNode])

  def compile(template: String): CompiledTemplate = {
    val nodes = mutable.ListBuffer[TemplateNode]()
    var remaining = template
    while (remaining.nonEmpty) {
      val exprStart = remaining.indexOf("${")
      val varStart = remaining.indexOf("#{")
      if (exprStart == -1 && varStart == -1) {
        nodes += LiteralNode(remaining)
        remaining = ""
      } else if (exprStart != -1 && (varStart == -1 || exprStart < varStart)) {
        if (exprStart > 0) nodes += LiteralNode(remaining.substring(0, exprStart))
        val end = remaining.indexOf("}", exprStart)
        val expr = remaining.substring(exprStart + 2, end)
        nodes += ExpressionNode(expr)
        remaining = remaining.substring(end + 1)
      } else {
        if (varStart > 0) nodes += LiteralNode(remaining.substring(0, varStart))
        val end = remaining.indexOf("}", varStart)
        val varName = remaining.substring(varStart + 2, end)
        nodes += VariableNode(varName)
        remaining = remaining.substring(end + 1)
      }
    }
    CompiledTemplate(nodes)
  }

  def render(compiled: CompiledTemplate, context: Map[String, String]): String = {
    compiled.nodes.map {
      case LiteralNode(text) => text
      case VariableNode(name) =>
        context.getOrElse(name, s"[undefined:$name]")
      case ExpressionNode(expr) =>
        evaluateExpression(expr, context)
    }.mkString
  }

  private def evaluateExpression(expr: String, context: Map[String, String]): String = {
    // Safe arithmetic and string operations only
    if (expr.matches("""[a-zA-Z0-9_+\-*/. ]+""")) {
      try {
        val resolved = context.foldLeft(expr) { case (e, (k, v)) =>
          e.replace(k, v)
        }
        evalArithmetic(resolved)
      } catch {
        case _: Exception => s"[error:$expr]"
      }
    } else {
      s"[restricted:$expr]"
    }
  }

  private def evalArithmetic(expr: String): String = {
    import scala.tools.reflect.ToolBox
    import scala.reflect.runtime.currentMirror
    val tb = currentMirror.mkToolBox()
    tb.eval(tb.parse(expr)).toString
  }
}

// Audit logging subsystem
object AuditLogger {
  private val logEntries = mutable.ListBuffer[AuditEntry]()
  private val logTemplate = "#{timestamp} | #{deviceId} | #{action} | #{details}"

  case class AuditEntry(timestamp: String, deviceId: String, action: String, details: String)

  def log(deviceId: String, action: String, details: String): Unit = {
    val entry = AuditEntry(Instant.now().toString, deviceId, action, details)
    logEntries += entry
  }

  def formatEntry(entry: AuditEntry): String = {
    val context = Map(
      "timestamp" -> entry.timestamp,
      "deviceId" -> entry.deviceId,
      "action" -> entry.action,
      "details" -> entry.details
    )
    val compiled = TemplateEngine.compile(logTemplate)
    TemplateEngine.render(compiled, context)
  }

  def getFormattedLogs(): List[String] = logEntries.map(formatEntry).toList
}

// Device status reporting with configurable templates
object DeviceStatusReporter {
  private var statusTemplate: String = "Device #{deviceId} | FW: #{firmwareVersion} | Up: ${uptime}"

  def setStatusTemplate(template: String): Unit = {
    // Security: only allow variable references, no expressions in user templates
    if (!template.contains("${")) {
      statusTemplate = template
    }
  }

  def generateReport(deviceId: String, fwVersion: String, uptimeHours: Int): String = {
    val context = Map(
      "deviceId" -> deviceId,
      "firmwareVersion" -> fwVersion,
      "uptime" -> uptimeHours.toString
    )
    val compiled = TemplateEngine.compile(statusTemplate)
    val report = TemplateEngine.render(compiled, context)
    AuditLogger.log(deviceId, "STATUS_REPORT", s"Generated report for $deviceId")
    report
  }
}

// Firmware update handler with audit trail
object FirmwareUpdateHandler {
  private val updateLogTemplate = "Update #{action}: #{details} on #{deviceId} at #{timestamp}"

  def processUpdate(deviceId: String, updatePayload: Map[String, String]): String = {
    val action = updatePayload.getOrElse("action", "unknown")
    val version = updatePayload.getOrElse("version", "unknown")
    val notes = updatePayload.getOrElse("notes", "")

    // Log the update attempt with details from payload
    AuditLogger.log(deviceId, action, s"version=$version notes=$notes")

    // Generate confirmation using template with payload data
    val confirmTemplate = s"Update ${action} confirmed for device #{deviceId} - $notes"
    val context = Map(
      "deviceId" -> deviceId,
      "action" -> action,
      "version" -> version,
      "timestamp" -> Instant.now().toString
    )
    val compiled = TemplateEngine.compile(confirmTemplate)
    TemplateEngine.render(compiled, context)
  }

  def getUpdateHistory(deviceId: String): List[String] = {
    AuditLogger.getFormattedLogs().filter(_.contains(deviceId))
  }
}

